CREATE TABLE IF NOT EXISTS `bank_list` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `card_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '卡类型',
  `card_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '卡姓名',
  `card_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '卡号',
  `initial_amount` decimal(10,2) DEFAULT '0.00' COMMENT '初始金额',
  `initial_office_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '初始办公金额',
  `bonus_amount` decimal(10,2) DEFAULT '0.00' COMMENT '上分金额',
  `deduction_amount` decimal(10,2) DEFAULT '0.00' COMMENT '下分金额',
  `transfer_in_amount` decimal(10,2) DEFAULT '0.00' COMMENT '转入金额',
  `transfer_out_amount` decimal(10,2) DEFAULT '0.00' COMMENT '转出金额',
  `handling_fee` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '手续费',
  `remaining_amount` decimal(10,2) DEFAULT '0.00' COMMENT '剩余金额',
  `office_amount` decimal(10,2) DEFAULT '0.00' COMMENT '办公金额',
  `card_status` varchar(20) DEFAULT '正常' COMMENT '卡状态（1正常  2冻结  3隐藏）',
  `optioner` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '操作人',
  `option_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '从operation_types获取字典参数',
  PRIMARY KEY (`Id`) USING BTREE,
  UNIQUE KEY `card_name` (`card_name`) USING BTREE,
  KEY `optioner` (`optioner`),
  KEY `card_type` (`card_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `bank_card_transaction_details` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `card_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '卡类型',
  `card_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '卡姓名',
  `card_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '卡号',
  `option_amount` decimal(10,2) DEFAULT '0.00' COMMENT '操作金额',
  `before_option_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '操作前金额',
  `create_at` timestamp NULL DEFAULT (now()) COMMENT '操作时间',
  `desk_number` varchar(50) DEFAULT NULL COMMENT '台号(群昵称)',
  `optioner` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '操作人',
  `option_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '从operation_types获取字典参数',
  `statistics_date` date DEFAULT NULL,
  `transfer_id` varchar(64) DEFAULT NULL COMMENT '银行卡转账关联号',
  `is_revoke` tinyint(1) NOT NULL DEFAULT '0' COMMENT '原转账是否已撤销',
  `revoke_of_id` int DEFAULT NULL COMMENT '冲正日志对应的原日志Id',
  PRIMARY KEY (`Id`) USING BTREE,
  UNIQUE KEY `uk_bank_card_revoke_of_id` (`revoke_of_id`),
  KEY `card_type` (`card_type`) USING BTREE,
  KEY `optioner` (`optioner`) USING BTREE,
  KEY `option_type` (`option_type`) USING BTREE,
  KEY `card_name` (`card_name`),
  KEY `create_at` (`create_at`),
  KEY `working_day` (`statistics_date`) USING BTREE,
  KEY `idx_bank_card_transfer_id` (`transfer_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='银行卡操作明细';

CREATE TABLE IF NOT EXISTS `card_transfer_registration` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `optioner` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '操作人',
  `option_time` timestamp NULL DEFAULT (now()) COMMENT '操作时间',
  `option_amount` decimal(10,2) DEFAULT '0.00' COMMENT '初始金额',
  `transfer_out_card_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '转出卡姓名',
  `transfer_out_card_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '转出卡类型',
  `before_transfer_out_amount` decimal(10,2) DEFAULT '0.00' COMMENT '转出前金额',
  `transfer_out_card_current_amount` decimal(10,2) DEFAULT '0.00' COMMENT '转出卡当前金额',
  `transfer_in_card_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT '' COMMENT '转出卡姓名',
  `transfer_in_card_type` varchar(50) DEFAULT '' COMMENT '转出卡类型',
  `transfer_in_amount` decimal(10,2) DEFAULT '0.00' COMMENT '转入前的金额',
  `transfer_in_card_current_amount` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '转入卡当前金额',
  `working_day` date NOT NULL DEFAULT (curdate()) COMMENT '工作日',
  `transfer_id` varchar(64) DEFAULT NULL COMMENT '银行卡转账关联号',
  `is_revoke` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否已撤销',
  PRIMARY KEY (`Id`),
  UNIQUE KEY `uk_card_transfer_registration_transfer_id` (`transfer_id`),
  KEY `working_day` (`working_day`),
  KEY `optioner` (`optioner`),
  KEY `option_time` (`option_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='银行卡间转账登记';

CREATE TABLE IF NOT EXISTS `office_expense_registration` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `project_name` varchar(50) DEFAULT NULL COMMENT '项目名称',
  `money` decimal(10,2) NOT NULL DEFAULT '0.00' COMMENT '金额',
  `option_money` decimal(10,2) DEFAULT '0.00' COMMENT '操作金额',
  `handler` varchar(50) DEFAULT NULL COMMENT '经手人',
  `option_time` timestamp NULL DEFAULT (curtime()) COMMENT '操作时间',
  `optioner` varchar(50) DEFAULT '' COMMENT '操作人',
  `card_name` varchar(50) DEFAULT '' COMMENT '卡姓名',
  `card_type` varchar(50) DEFAULT NULL COMMENT '卡类型',
  `befor_opton_money` decimal(10,2) DEFAULT '0.00' COMMENT '操作前金额',
  `left_money` decimal(10,2) DEFAULT '0.00' COMMENT '剩余金额',
  `working_date` date DEFAULT (curdate()),
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  PRIMARY KEY (`Id`),
  KEY `project_name` (`project_name`),
  KEY `working_date` (`working_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='办公费用登录';

